import { describe, expect, it, vi } from 'vitest'
import { createStore } from 'zustand/vanilla'

class Point {
  x: number
  y: number
  constructor(x: number, y: number) {
    this.x = x
    this.y = y
  }
  length(): number {
    return Math.hypot(this.x, this.y)
  }
}

describe('setState merges only plain objects', () => {
  it('replaces array state instead of merging it into an object', () => {
    const store = createStore<number[]>(() => [1, 2, 3])
    const next = [9]
    store.setState(next)
    expect(Array.isArray(store.getState())).toBe(true)
    expect(store.getState()).toBe(next)
    store.setState((prev) => [...prev, 10])
    expect(Array.isArray(store.getState())).toBe(true)
    expect(store.getState()).toEqual([9, 10])
  })

  it('replaces Map and Set state', () => {
    const mapStore = createStore<Map<string, number>>(
      () => new Map([['a', 1]]),
    )
    const nextMap = new Map([['b', 2]])
    mapStore.setState(nextMap)
    expect(mapStore.getState()).toBe(nextMap)
    expect(mapStore.getState().get('b')).toBe(2)
    expect(mapStore.getState().has('a')).toBe(false)

    const setStore = createStore<Set<string>>(() => new Set(['x']))
    setStore.setState((prev) => new Set([...prev, 'y']))
    expect(setStore.getState()).toBeInstanceOf(Set)
    expect([...setStore.getState()]).toEqual(['x', 'y'])
  })

  it('replaces class instance state, keeping its prototype', () => {
    const store = createStore<Point>(() => new Point(0, 0))
    const next = new Point(3, 4)
    store.setState(next)
    expect(store.getState()).toBe(next)
    expect(store.getState()).toBeInstanceOf(Point)
    expect(store.getState().length()).toBe(5)
  })

  it('notifies listeners with the new non-plain state and the previous one', () => {
    const initial = [1]
    const store = createStore<number[]>(() => initial)
    const listener = vi.fn()
    store.subscribe(listener)
    const next = [2, 3]
    store.setState(next)
    expect(listener).toHaveBeenCalledTimes(1)
    expect(listener).toHaveBeenCalledWith(next, initial)
  })

  it('still shallow-merges plain object partials, including null-prototype ones', () => {
    type State = { count: number; items: number[]; label: string }
    const initial: State = { count: 0, items: [1], label: 'a' }
    const store = createStore<State>(() => initial)
    const partial = { items: [2, 3] }
    store.setState(partial)
    expect(store.getState()).toEqual({ count: 0, items: [2, 3], label: 'a' })
    expect(store.getState()).not.toBe(partial)
    expect(initial).toEqual({ count: 0, items: [1], label: 'a' })
    store.setState((s) => ({ count: s.count + 1 }))
    expect(store.getState()).toEqual({ count: 1, items: [2, 3], label: 'a' })
    const bare: Partial<State> = Object.assign(Object.create(null), {
      label: 'b',
    })
    store.setState(bare)
    expect(store.getState()).toEqual({ count: 1, items: [2, 3], label: 'b' })
  })

  it('keeps primitive, null and explicit replace behavior', () => {
    const numberStore = createStore<number>(() => 1)
    numberStore.setState((n) => n + 1)
    expect(numberStore.getState()).toBe(2)

    const nullable = createStore<{ a: number } | null>(() => ({ a: 1 }))
    nullable.setState(null)
    expect(nullable.getState()).toBe(null)

    const replaced = createStore<{ a?: number; b?: number }>(() => ({ a: 1 }))
    replaced.setState({ b: 2 }, true)
    expect(replaced.getState()).toEqual({ b: 2 })

    const listener = vi.fn()
    const same = createStore<number[]>(() => [1])
    same.subscribe(listener)
    same.setState(same.getState())
    expect(listener).not.toHaveBeenCalled()
  })
})

