import { act, render, screen } from '@testing-library/react'
import { describe, expect, it } from 'vitest'
import { create } from 'zustand'
import { useShallow } from 'zustand/react/shallow'
import { shallow } from 'zustand/vanilla/shallow'

const qs = (text: string) => new URLSearchParams(text)

describe('shallow with repeated keys in keyed iterables', () => {
  it('is false when one side has more values for a key', () => {
    expect(shallow(qs('tag=a&tag=b'), qs('tag=b'))).toBe(false)
    expect(shallow(qs('tag=b'), qs('tag=a&tag=b'))).toBe(false)
  })

  it('is false when repeated values differ but the last ones match', () => {
    expect(shallow(qs('a=1&a=2'), qs('a=2&a=2'))).toBe(false)
    expect(shallow(qs('a=1&a=2&b=3'), qs('a=2&b=3&b=3'))).toBe(false)
  })

  it('treats the order of values of one key as significant', () => {
    expect(shallow(qs('a=1&a=2'), qs('a=2&a=1'))).toBe(false)
  })

  it('ignores the relative order of different keys', () => {
    expect(shallow(qs('a=1&a=2'), qs('a=1&a=2'))).toBe(true)
    expect(shallow(qs('a=1&b=2&a=3'), qs('b=2&a=1&a=3'))).toBe(true)
    expect(shallow(qs('a=1&b=2'), qs('b=2&a=1'))).toBe(true)
    expect(shallow(qs('a=1'), qs('a=2'))).toBe(false)
  })

  it('applies to FormData too', () => {
    const fd = (...pairs: [string, string][]) => {
      const data = new FormData()
      for (const [key, value] of pairs) data.append(key, value)
      return data
    }
    expect(shallow(fd(['f', 'x'], ['f', 'y']), fd(['f', 'y']))).toBe(false)
    expect(shallow(fd(['f', 'x'], ['f', 'y']), fd(['f', 'y'], ['f', 'y']))).toBe(
      false,
    )
    expect(
      shallow(fd(['f', 'x'], ['g', 'z'], ['f', 'y']), fd(['g', 'z'], ['f', 'x'], ['f', 'y'])),
    ).toBe(true)
  })

  it('keeps Map, Set, array and object comparisons unchanged', () => {
    expect(
      shallow(
        new Map<string, unknown>([
          ['a', 1],
          ['b', 2],
        ]),
        new Map<string, unknown>([
          ['b', 2],
          ['a', 1],
        ]),
      ),
    ).toBe(true)
    expect(shallow(new Map([['a', 1]]), new Map([['a', 2]]))).toBe(false)
    expect(shallow(new Set([1, 2]), new Set([2, 1]))).toBe(true)
    expect(shallow(new Set([1, 2]), new Set([1, 3]))).toBe(false)
    expect(shallow([1, 2, 3], [1, 2, 3])).toBe(true)
    expect(shallow([1, 2, 3], [3, 2, 1])).toBe(false)
    expect(shallow([1, 2], [1, 2, 3])).toBe(false)
    expect(shallow({ a: 1, b: 2 }, { b: 2, a: 1 })).toBe(true)
    expect(shallow({ a: 1 }, { a: 1, b: 2 })).toBe(false)
  })

  it('lets useShallow re-render when a repeated key is added', () => {
    const useStore = create<{ params: URLSearchParams }>(() => ({
      params: qs('tag=b'),
    }))
    let renders = 0
    const Tags = () => {
      const params = useStore(useShallow((s) => s.params))
      renders++
      return <div>tags:{params.getAll('tag').join(',')}</div>
    }
    render(<Tags />)
    expect(screen.getByText('tags:b')).toBeInTheDocument()
    act(() => {
      useStore.setState({ params: qs('tag=a&tag=b') })
    })
    expect(screen.getByText('tags:a,b')).toBeInTheDocument()
    const before = renders
    act(() => {
      useStore.setState({ params: qs('tag=a&tag=b') })
    })
    expect(renders).toBe(before)
    expect(screen.getByText('tags:a,b')).toBeInTheDocument()
  })
})

