// Group values by key: keyed iterables like URLSearchParams can repeat keys
const groupEntries = (value: { entries(): Iterable<[unknown, unknown]> }) => {
  const groups = new Map<unknown, unknown[]>()
  for (const [key, item] of value.entries()) {
    const group = groups.get(key)
    if (group) {
      group.push(item)
    } else {
      groups.set(key, [item])
    }
  }
  return groups
}

const compareEntries = (
  valueA: { entries(): Iterable<[unknown, unknown]> },
  valueB: { entries(): Iterable<[unknown, unknown]> },
) => {
  const mapA = groupEntries(valueA)
  const mapB = groupEntries(valueB)
  if (mapA.size !== mapB.size) {
    return false
  }
  for (const [key, itemsA] of mapA) {
    const itemsB = mapB.get(key)
    if (
      !itemsB ||
      itemsA.length !== itemsB.length ||
      itemsA.some((item, index) => !Object.is(item, itemsB[index]))
    ) {
      return false
    }
  }
  return true
}

