import { useState } from 'react'
import { act, fireEvent, render, screen } from '@testing-library/react'
import { describe, expect, it } from 'vitest'
import { create, useStore } from 'zustand'
import { createStore } from 'zustand/vanilla'

type CountState = { count: number }

class CounterStore {
  private state: CountState
  private readonly initial: CountState
  private readonly listeners = new Set<
    (state: CountState, prev: CountState) => void
  >()
  subscribeCalls = 0

  constructor(count: number) {
    this.state = { count }
    this.initial = this.state
  }

  getState(): CountState {
    return this.state
  }

  getInitialState(): CountState {
    return this.initial
  }

  subscribe(listener: (state: CountState, prev: CountState) => void) {
    this.subscribeCalls++
    this.listeners.add(listener)
    return () => {
      this.listeners.delete(listener)
    }
  }

  increment() {
    const prev = this.state
    this.state = { count: prev.count + 1 }
    this.listeners.forEach((listener) => listener(this.state, prev))
  }

  get listenerCount() {
    return this.listeners.size
  }
}

describe('useStore with external stores whose methods use this', () => {
  it('renders, re-renders on change and unsubscribes on unmount', () => {
    const store = new CounterStore(5)

    function Counter() {
      const count = useStore(store, (s) => s.count)
      return <div>count: {count}</div>
    }

    const { unmount } = render(<Counter />)
    expect(screen.getByText('count: 5')).toBeInTheDocument()
    expect(store.listenerCount).toBe(1)

    act(() => store.increment())
    expect(screen.getByText('count: 6')).toBeInTheDocument()

    act(() => store.increment())
    expect(screen.getByText('count: 7')).toBeInTheDocument()

    unmount()
    expect(store.listenerCount).toBe(0)
  })

  it('works without a selector', () => {
    const store = new CounterStore(1)

    function Counter() {
      const state = useStore(store)
      return <div>whole: {state.count}</div>
    }

    render(<Counter />)
    expect(screen.getByText('whole: 1')).toBeInTheDocument()
    act(() => store.increment())
    expect(screen.getByText('whole: 2')).toBeInTheDocument()
  })

  it('does not resubscribe on ordinary re-renders', () => {
    const store = new CounterStore(0)

    function Counter() {
      const [clicks, setClicks] = useState(0)
      const count = useStore(store, (s) => s.count)
      return (
        <button onClick={() => setClicks((c) => c + 1)}>
          count: {count}, clicks: {clicks}
        </button>
      )
    }

    render(<Counter />)
    const subscribedAfterMount = store.subscribeCalls
    expect(subscribedAfterMount).toBe(1)

    fireEvent.click(screen.getByRole('button'))
    fireEvent.click(screen.getByRole('button'))
    act(() => store.increment())
    fireEvent.click(screen.getByRole('button'))
    expect(screen.getByText('count: 1, clicks: 3')).toBeInTheDocument()

    expect(store.subscribeCalls).toBe(subscribedAfterMount)
    expect(store.listenerCount).toBe(1)
  })

  it('follows the store when a different store instance is passed', () => {
    const first = new CounterStore(10)
    const second = new CounterStore(20)

    function Counter({ store }: { store: CounterStore }) {
      const count = useStore(store, (s) => s.count)
      return <div>value: {count}</div>
    }

    const { rerender } = render(<Counter store={first} />)
    expect(screen.getByText('value: 10')).toBeInTheDocument()

    rerender(<Counter store={second} />)
    expect(screen.getByText('value: 20')).toBeInTheDocument()
    expect(first.listenerCount).toBe(0)
    expect(second.listenerCount).toBe(1)

    act(() => second.increment())
    expect(screen.getByText('value: 21')).toBeInTheDocument()
    act(() => first.increment())
    expect(screen.getByText('value: 21')).toBeInTheDocument()
  })

  it('keeps working with zustand stores and bound hooks', () => {
    const vanilla = createStore<CountState>(() => ({ count: 3 }))
    const useBound = create<CountState>(() => ({ count: 30 }))

    function Both() {
      const a = useStore(vanilla, (s) => s.count)
      const b = useBound((s) => s.count)
      return (
        <div>
          a: {a}, b: {b}
        </div>
      )
    }

    render(<Both />)
    expect(screen.getByText('a: 3, b: 30')).toBeInTheDocument()
    act(() => vanilla.setState({ count: 4 }))
    act(() => useBound.setState({ count: 31 }))
    expect(screen.getByText('a: 4, b: 31')).toBeInTheDocument()
  })
})

