import { useEffect, useState } from 'react'
import { act, fireEvent, render, screen } from '@testing-library/react'
import { describe, expect, it } from 'vitest'
import { create } from 'zustand'
import { useShallow } from 'zustand/react/shallow'

type Todo = { id: number; title: string; done: boolean }
type TodoState = { todos: Todo[]; filter: string; visits: number }

const makeStore = () =>
  create<TodoState>(() => ({
    todos: [
      { id: 1, title: 'milk', done: false },
      { id: 2, title: 'eggs', done: true },
      { id: 3, title: 'bread', done: false },
    ],
    filter: 'all',
    visits: 0,
  }))

describe('useShallow selector identity', () => {
  it('returns the same function across re-renders', () => {
    const useTodos = makeStore()
    const seen = new Set<unknown>()
    let effectRuns = 0

    function Titles({ prefix }: { prefix: string }) {
      const [clicks, setClicks] = useState(0)
      const select = useShallow((s: TodoState) =>
        s.todos.map((t) => prefix + t.title),
      )
      seen.add(select)
      useEffect(() => {
        effectRuns++
      }, [select])
      const titles = useTodos(select)
      return (
        <button onClick={() => setClicks((c) => c + 1)}>
          {titles.join(',')}|{clicks}
        </button>
      )
    }

    const { rerender } = render(<Titles prefix="-" />)
    fireEvent.click(screen.getByRole('button'))
    fireEvent.click(screen.getByRole('button'))
    act(() => useTodos.setState({ visits: 1 }))
    act(() =>
      useTodos.setState((s) => ({
        todos: [...s.todos, { id: 4, title: 'jam', done: false }],
      })),
    )
    rerender(<Titles prefix="+" />)

    expect(screen.getByRole('button')).toHaveTextContent(
      '+milk,+eggs,+bread,+jam|2',
    )
    expect(seen.size).toBe(1)
    expect(effectRuns).toBe(1)
  })

  it('always uses the selector passed in the current render', () => {
    const useTodos = makeStore()

    function Filtered() {
      const [onlyDone, setOnlyDone] = useState(false)
      const titles = useTodos(
        useShallow((s) =>
          s.todos.filter((t) => !onlyDone || t.done).map((t) => t.title),
        ),
      )
      return (
        <button onClick={() => setOnlyDone((v) => !v)}>
          {titles.join(',')}
        </button>
      )
    }

    render(<Filtered />)
    const button = screen.getByRole('button')
    expect(button).toHaveTextContent('milk,eggs,bread')
    fireEvent.click(button)
    expect(button).toHaveTextContent(/^eggs$/)
    fireEvent.click(button)
    expect(button).toHaveTextContent('milk,eggs,bread')
  })

  it('reflects a changed prop immediately, without a store update', () => {
    const useTodos = makeStore()

    function Item({ id }: { id: number }) {
      const [title, done] = useTodos(
        useShallow((s) => {
          const todo = s.todos.find((t) => t.id === id)
          return [todo?.title, todo?.done]
        }),
      )
      return (
        <p>
          {title}:{String(done)}
        </p>
      )
    }

    const { rerender } = render(<Item id={1} />)
    expect(screen.getByText('milk:false')).toBeInTheDocument()
    rerender(<Item id={2} />)
    expect(screen.getByText('eggs:true')).toBeInTheDocument()
    rerender(<Item id={3} />)
    expect(screen.getByText('bread:false')).toBeInTheDocument()
  })

  it('keeps shallow-equal results stable and skips needless re-renders', () => {
    const useTodos = makeStore()
    let renders = 0
    const outputs = new Set<unknown>()

    function Open() {
      const open = useTodos(
        useShallow((s) => s.todos.filter((t) => !t.done).map((t) => t.id)),
      )
      renders++
      outputs.add(open)
      return <p>open: {open.join(',')}</p>
    }

    render(<Open />)
    expect(screen.getByText('open: 1,3')).toBeInTheDocument()
    act(() => useTodos.setState({ visits: 5 }))
    act(() =>
      useTodos.setState((s) => ({
        todos: s.todos.map((t) => (t.id === 1 ? { ...t, title: 'oat' } : t)),
      })),
    )
    expect(renders).toBe(1)
    expect(outputs.size).toBe(1)

    act(() =>
      useTodos.setState((s) => ({
        todos: s.todos.map((t) => (t.id === 2 ? { ...t, done: false } : t)),
      })),
    )
    expect(screen.getByText('open: 1,2,3')).toBeInTheDocument()
    expect(renders).toBe(2)
  })

  it('keeps a separate cache for each component using it', () => {
    const useTodos = makeStore()
    const selectors: unknown[] = []

    function Count({ done }: { done: boolean }) {
      const select = useShallow((s: TodoState) =>
        s.todos.filter((t) => t.done === done).map((t) => t.title),
      )
      selectors.push(select)
      const titles = useTodos(select)
      return (
        <p>
          {String(done)}={titles.join(',')}
        </p>
      )
    }

    render(
      <>
        <Count done={true} />
        <Count done={false} />
      </>,
    )
    expect(screen.getByText('true=eggs')).toBeInTheDocument()
    expect(screen.getByText('false=milk,bread')).toBeInTheDocument()
    expect(selectors[0]).not.toBe(selectors[1])

    act(() =>
      useTodos.setState((s) => ({
        todos: s.todos.map((t) => ({ ...t, done: !t.done })),
      })),
    )
    expect(screen.getByText('true=milk,bread')).toBeInTheDocument()
    expect(screen.getByText('false=eggs')).toBeInTheDocument()
  })
})

