import { act, render, screen } from '@testing-library/react'
import { describe, expect, it } from 'vitest'
import { shallow } from 'zustand/shallow'
import {
  createWithEqualityFn,
  useStoreWithEqualityFn,
} from 'zustand/traditional'
import { createStore } from 'zustand/vanilla'

type State = { list: number[]; other: number }

const initial = (): State => ({ list: [1, 2], other: 0 })

describe('null equalityFn means "no equality function"', () => {
  it('useStoreWithEqualityFn(api, selector, null) compares by reference', () => {
    const api = createStore<State>(initial)
    let renders = 0
    function List() {
      const list = useStoreWithEqualityFn(api, (s) => s.list, null as any)
      renders++
      return <div>list: {list.join(',')}</div>
    }
    render(<List />)
    expect(screen.getByText('list: 1,2')).toBeInTheDocument()
    expect(renders).toBe(1)

    act(() => api.setState({ other: 1 }))
    expect(renders).toBe(1)

    act(() => api.setState({ list: [1, 2] }))
    expect(renders).toBe(2)
    expect(screen.getByText('list: 1,2')).toBeInTheDocument()

    act(() => api.setState({ list: [3] }))
    expect(renders).toBe(3)
    expect(screen.getByText('list: 3')).toBeInTheDocument()
  })

  it('a null equalityFn on a createWithEqualityFn hook skips the store default', () => {
    const useListStore = createWithEqualityFn<State>(initial, shallow)
    let strictRenders = 0
    function Strict() {
      const list = useListStore((s) => s.list, null as any)
      strictRenders++
      return <div>strict: {list.join(',')}</div>
    }
    render(<Strict />)
    expect(strictRenders).toBe(1)

    act(() => useListStore.setState({ other: 1 }))
    expect(strictRenders).toBe(1)

    act(() => useListStore.setState({ list: [1, 2] }))
    expect(strictRenders).toBe(2)

    act(() => useListStore.setState({ list: [4, 5] }))
    expect(strictRenders).toBe(3)
    expect(screen.getByText('strict: 4,5')).toBeInTheDocument()
  })

  it('omitting the equalityFn or passing undefined still uses the store default', () => {
    const useListStore = createWithEqualityFn<State>(initial, shallow)
    let omittedRenders = 0
    let undefinedRenders = 0
    let strictRenders = 0
    function Omitted() {
      const list = useListStore((s) => s.list)
      omittedRenders++
      return <div>omitted: {list.join(',')}</div>
    }
    function ExplicitUndefined() {
      const list = useListStore((s) => s.list, undefined)
      undefinedRenders++
      return <div>undefined: {list.join(',')}</div>
    }
    function Strict() {
      const list = useListStore((s) => s.list, null as any)
      strictRenders++
      return <div>strict: {list.join(',')}</div>
    }
    render(
      <>
        <Omitted />
        <ExplicitUndefined />
        <Strict />
