import { useState } from 'react'
import { act, fireEvent, render, screen } from '@testing-library/react'
import { describe, expect, it, vi } from 'vitest'
import {
  createWithEqualityFn,
  useStoreWithEqualityFn,
} from 'zustand/traditional'
import { createStore } from 'zustand/vanilla'

type State = { items: number[]; other: number }

const initial = (): State => ({ items: [1, 2], other: 0 })
const stableSelectItems = (s: State) => s.items

describe('inline equality functions and selector memoization', () => {
  it('useStoreWithEqualityFn does not re-run a stable selector when only the equality fn identity changes', () => {
    const api = createStore<State>(initial)
    const selectItems = vi.fn((s: State) => s.items)
    function Items() {
      const [clicks, setClicks] = useState(0)
      const items = useStoreWithEqualityFn(
        api,
        selectItems,
        (a, b) => a.length === b.length,
      )
      return (
        <button onClick={() => setClicks((c) => c + 1)}>
          clicks: {clicks} items: {items.join(',')}
        </button>
      )
    }
    render(<Items />)
    const callsAfterMount = selectItems.mock.calls.length
    expect(callsAfterMount).toBeGreaterThan(0)

    fireEvent.click(screen.getByRole('button'))
    fireEvent.click(screen.getByRole('button'))
    fireEvent.click(screen.getByRole('button'))
    expect(screen.getByText('clicks: 3 items: 1,2')).toBeInTheDocument()
    expect(selectItems).toHaveBeenCalledTimes(callsAfterMount)
  })

  it('hooks from createWithEqualityFn do not re-run a stable selector for an inline per-call equality fn', () => {
    const useItemsStore = createWithEqualityFn<State>(initial)
    const selectItems = vi.fn((s: State) => s.items)
    function Items() {
      const [clicks, setClicks] = useState(0)
      const items = useItemsStore(selectItems, (a, b) => a.length === b.length)
      return (
        <button onClick={() => setClicks((c) => c + 1)}>
          clicks: {clicks} items: {items.join(',')}
        </button>
      )
    }
    render(<Items />)
    const callsAfterMount = selectItems.mock.calls.length

    fireEvent.click(screen.getByRole('button'))
    fireEvent.click(screen.getByRole('button'))
    expect(screen.getByText('clicks: 2 items: 1,2')).toBeInTheDocument()
    expect(selectItems).toHaveBeenCalledTimes(callsAfterMount)
  })

  it('an inline equality fn still decides re-renders on store updates', () => {
    const useItemsStore = createWithEqualityFn<State>(initial)
    let renders = 0
    function Items() {
      const items = useItemsStore(
        (s) => s.items,
        (a, b) => a.length === b.length,
      )
      renders++
      return <div>items: {items.join(',')}</div>
    }
    render(<Items />)
    expect(renders).toBe(1)

    act(() => useItemsStore.setState({ items: [3, 4] }))
    expect(renders).toBe(1)
    expect(screen.getByText('items: 1,2')).toBeInTheDocument()

    act(() => useItemsStore.setState({ items: [5] }))
    expect(renders).toBe(2)
    expect(screen.getByText('items: 5')).toBeInTheDocument()
  })

  it('the equality fn from the latest render is the one used on the next store update', () => {
    const api = createStore<State>(initial)
    function Items({ lengthOnly }: { lengthOnly: boolean }) {
      const items = useStoreWithEqualityFn(api, stableSelectItems, (a, b) =>
        lengthOnly
          ? a.length === b.length
          : a.length === b.length && a.every((x, i) => x === b[i]),
      )
      return <div>items: {items.join(',')}</div>
    }
    const { rerender } = render(<Items lengthOnly />)
    act(() => api.setState({ items: [3, 4] }))
    expect(screen.getByText('items: 1,2')).toBeInTheDocument()

    rerender(<Items lengthOnly={false} />)
    act(() => api.setState({ items: [5, 6] }))
    expect(screen.getByText('items: 5,6')).toBeInTheDocument()

    rerender(<Items lengthOnly />)
    act(() => api.setState({ items: [7, 8] }))
    expect(screen.getByText('items: 5,6')).toBeInTheDocument()

    act(() => api.setState({ items: [9] }))
    expect(screen.getByText('items: 9')).toBeInTheDocument()
  })

  it('the latest per-call equality fn of a createWithEqualityFn hook is used, overriding the store default', () => {
    const neverEqual = () => false
    const useItemsStore = createWithEqualityFn<State>(initial, neverEqual)
    function Items({ frozen }: { frozen: boolean }) {
      const items = useItemsStore(stableSelectItems, (a, b) => frozen || a === b)
      return <div>items: {items.join(',')}</div>
    }
    const { rerender } = render(<Items frozen />)
    act(() => useItemsStore.setState({ items: [3] }))
    expect(screen.getByText('items: 1,2')).toBeInTheDocument()

    rerender(<Items frozen={false} />)
    act(() => useItemsStore.setState({ items: [4] }))
    expect(screen.getByText('items: 4')).toBeInTheDocument()
  })

  it('without an equality fn a stable selector is still not re-run on re-render and updates still render', () => {
    const api = createStore<State>(initial)
    const selectItems = vi.fn((s: State) => s.items)
    function Items() {
      const [clicks, setClicks] = useState(0)
      const items = useStoreWithEqualityFn(api, selectItems)
      return (
        <button onClick={() => setClicks((c) => c + 1)}>
          clicks: {clicks} items: {items.join(',')}
        </button>
      )
    }
    render(<Items />)
    const callsAfterMount = selectItems.mock.calls.length
    fireEvent.click(screen.getByRole('button'))
    expect(selectItems).toHaveBeenCalledTimes(callsAfterMount)

    act(() => api.setState({ items: [1, 2] }))
    expect(screen.getByText('clicks: 1 items: 1,2')).toBeInTheDocument()
    act(() => api.setState({ items: [6] }))
    expect(screen.getByText('clicks: 1 items: 6')).toBeInTheDocument()
  })
})

