  equalityFn?: (a: StateSlice, b: StateSlice) => boolean,
) {
  // Read the latest equality fn through a ref so that a new (e.g. inline)
  // function on every render does not invalidate the memoized selection.
  const equalityFnRef = React.useRef(equalityFn)
  equalityFnRef.current = equalityFn
  const hasEqualityFn = equalityFn !== undefined
  const isEqual = React.useMemo(
    () =>
      hasEqualityFn
        ? (a: StateSlice, b: StateSlice) => equalityFnRef.current!(a, b)
        : undefined,
    [hasEqualityFn],
  )
  const slice = useSyncExternalStoreWithSelector(
    api.subscribe,
    api.getState,
    api.getInitialState,
    selector,
    isEqual,
  )

