  }
}

const asyncMemoryStorage = (initial: Record<string, string>) => {
  const sync = memoryStorage(initial)
  return {
    data: sync.data,
    setItem: sync.setItem,
    getItem: async (name: string) => sync.getItem(name),
    removeItem: async (name: string) => sync.removeItem(name),
  }
}

