import { describe, expect, it, vi } from 'vitest'
import { create } from 'zustand'
import { createJSONStorage, persist } from 'zustand/middleware'
import type { PersistStorage, StorageValue } from 'zustand/middleware'

// A minimal promise-like value, as produced by third-party promise libraries
// or by promises from another realm: it implements `then` and nothing else.
type Foreign<T> = {
  then: (
    onFulfilled?: ((value: T) => unknown) | null,
    onRejected?: ((reason: unknown) => unknown) | null,
  ) => Foreign<unknown>
}
const wrap = <T,>(start: () => Promise<T>): Foreign<T> => ({
  then: (onFulfilled, onRejected) => {
    const next = start().then(onFulfilled, onRejected)
    return wrap(() => next)
  },
})
const resolved = <T,>(value: T): Foreign<T> => wrap(() => Promise.resolve(value))
const rejected = (reason: unknown): Foreign<never> =>
  wrap(() => Promise.reject(reason))

type Counter = { count: number; name: string }

const hydration = () => {
  let finish!: (result: { state: Counter | undefined; error: unknown }) => void
  const done = new Promise<{ state: Counter | undefined; error: unknown }>((resolve) => {
    finish = resolve
  })
  return {
    done,
    onRehydrateStorage: () => (state?: Counter, error?: unknown) =>
      finish({ state, error }),
  }
}

describe('persist with non-native thenables', () => {
  it('hydrates through createJSONStorage when getItem returns a thenable', async () => {
    const storage = {
      getItem: (name: string) =>
        resolved(
          JSON.stringify({ state: { count: 7, name }, version: 0 }),
        ) as unknown as Promise<string | null>,
      setItem: vi.fn(),
      removeItem: () => {},
    }
    const { done, onRehydrateStorage } = hydration()
    const store = create<Counter>()(
      persist(() => ({ count: 0, name: '' }), {
        name: 'thenable-json',
        storage: createJSONStorage(() => storage),
        onRehydrateStorage,
      }),
    )

    const { state, error } = await done
    expect(error).toBeUndefined()
    expect(state).toEqual({ count: 7, name: 'thenable-json' })
    expect(store.getState()).toEqual({ count: 7, name: 'thenable-json' })
    expect(store.persist.hasHydrated()).toBe(true)
  })

