    expect(asyncStore.persist.hasHydrated()).toBe(false)
    const { state, error } = await done
    expect(error).toBeUndefined()
    expect(state).toEqual({ count: 3, name: 'native' })
    expect(asyncStore.getState()).toEqual({ count: 3, name: 'native' })
  })
})

