import { describe, expect, it, vi } from 'vitest'
import { create } from 'zustand'
import { subscribeWithSelector } from 'zustand/middleware'
import { createStore } from 'zustand/vanilla'

type State = {
  count: number
  other: string
  items: number[]
  inc: () => void
}

const sameItems = (a: number[], b: number[]) =>
  a.length === b.length && a.every((value, index) => Object.is(value, b[index]))

type Api = {
  subscribe: {
    <U>(
      selector: (state: State) => U,
      listener: (selected: U, previous: U) => void,
      options?: { equalityFn?: (a: U, b: U) => boolean; fireImmediately?: boolean },
    ): () => void
  }
}

const makeStore = (wire: (api: Api) => void, items: number[] = []) =>
  createStore<State>()(
    subscribeWithSelector((set, _get, api) => {
      wire(api as unknown as Api)
      return {
        count: 0,
        other: 'a',
        items,
        inc: () => set((s) => ({ count: s.count + 1 })),
      }
    }),
  )

describe('subscribeWithSelector: subscribing inside the state creator', () => {
  it('does not throw and never runs the selector on an undefined state', () => {
    const seen: unknown[] = []
    const listener = vi.fn()
    let store: ReturnType<typeof makeStore> | undefined
    expect(() => {
      store = makeStore((api) => {
        api.subscribe((s) => {
          seen.push(s)
          return s.count
        }, listener)
      })
    }).not.toThrow()
    store!.setState({ count: 1 })
    expect(seen.length).toBeGreaterThan(0)
    expect(seen.every((s) => s !== undefined && s !== null)).toBe(true)
    expect(listener).toHaveBeenCalledTimes(1)
    expect(listener).toHaveBeenCalledWith(1, 0)
  })

  it('compares the first update against the initial slice, then against the last one', () => {
    const listener = vi.fn()
    const store = makeStore((api) => {
      api.subscribe((s) => s.count, listener)
    })
    expect(listener).not.toHaveBeenCalled()
    store.getState().inc()
    expect(listener).toHaveBeenCalledTimes(1)
    expect(listener).toHaveBeenLastCalledWith(1, 0)
    store.getState().inc()
    expect(listener).toHaveBeenCalledTimes(2)
    expect(listener).toHaveBeenLastCalledWith(2, 1)
  })

  it('does not fire for updates that leave the selected slice unchanged', () => {
    const listener = vi.fn()
    const store = makeStore((api) => {
      api.subscribe((s) => s.count, listener)
    })
    store.setState({ other: 'b' })
    store.setState({ other: 'c' })
    expect(listener).not.toHaveBeenCalled()
    store.setState({ count: 5 })
    expect(listener).toHaveBeenCalledTimes(1)
    expect(listener).toHaveBeenCalledWith(5, 0)
  })

  it('uses equalityFn starting from the initial slice', () => {
    const initialItems = [1, 2]
    const listener = vi.fn()
    const store = makeStore((api) => {
      api.subscribe((s) => s.items, listener, { equalityFn: sameItems })
    }, initialItems)
    store.setState({ items: [1, 2] })
    expect(listener).not.toHaveBeenCalled()
    store.setState({ items: [1, 2, 3] })
    expect(listener).toHaveBeenCalledTimes(1)
    expect(listener.mock.calls[0]![0]).toEqual([1, 2, 3])
    expect(listener.mock.calls[0]![1]).toBe(initialItems)
  })

  it('returns a working unsubscribe function', () => {
    const listener = vi.fn()
    let unsubscribe: (() => void) | undefined
    const store = makeStore((api) => {
      unsubscribe = api.subscribe((s) => s.count, listener)
    })
    expect(typeof unsubscribe).toBe('function')
    unsubscribe!()
    store.setState({ count: 3 })
    expect(listener).not.toHaveBeenCalled()
  })

  it('works with the React create() entry point too', () => {
    const listener = vi.fn()
    const useStore = create<State>()(
      subscribeWithSelector((set, _get, api) => {
        api.subscribe((s) => s.count, listener)
        return {
          count: 10,
          other: 'a',
          items: [],
          inc: () => set((s) => ({ count: s.count + 1 })),
        }
      }),
    )
    useStore.getState().inc()
    expect(listener).toHaveBeenCalledTimes(1)
    expect(listener).toHaveBeenCalledWith(11, 10)
  })

  it('keeps subscriptions made after creation working, including fireImmediately', () => {
    const store = createStore<State>()(
      subscribeWithSelector((set) => ({
        count: 3,
        other: 'a',
        items: [],
        inc: () => set((s) => ({ count: s.count + 1 })),
      })),
    )
    const immediate = vi.fn()
    const plain = vi.fn()
    store.subscribe((s) => s.count, immediate, { fireImmediately: true })
    store.subscribe((s) => s.count, plain)
    expect(immediate).toHaveBeenCalledTimes(1)
    expect(immediate).toHaveBeenCalledWith(3, 3)
    expect(plain).not.toHaveBeenCalled()
    store.setState({ other: 'z' })
    expect(immediate).toHaveBeenCalledTimes(1)
    expect(plain).not.toHaveBeenCalled()
    store.getState().inc()
    expect(immediate).toHaveBeenLastCalledWith(4, 3)
    expect(plain).toHaveBeenCalledWith(4, 3)
    expect(plain).toHaveBeenCalledTimes(1)
  })
})

