import { describe, expect, it, vi } from 'vitest'
import { createJSONStorage, persist } from 'zustand/middleware'
import { createStore } from 'zustand/vanilla'

type State = { user: string; count: number }

type Deferred<T> = { promise: Promise<T>; resolve: (value: T) => void }

const deferred = <T,>(): Deferred<T> => {
  let resolve!: (value: T) => void
  const promise = new Promise<T>((r) => {
    resolve = r
  })
  return { promise, resolve }
}

// Let every pending promise chain settle (no timers involved).
const flush = async () => {
  for (let i = 0; i < 50; i++) await Promise.resolve()
}

const stored = (state: State, version = 0) => JSON.stringify({ state, version })

const initial: State = { user: 'none', count: 0 }

// An async storage whose reads resolve only when the test says so.
const controlledStorage = () => {
  const reads: { name: string; result: Deferred<string | null> }[] = []
  const setItem = vi.fn()
  const raw = {
    getItem: (name: string) => {
      const result = deferred<string | null>()
      reads.push({ name, result })
      return result.promise
    },
    setItem: (name: string, value: string) => {
      setItem(name, value)
    },
    removeItem: () => {},
  }
  return { reads, setItem, storage: createJSONStorage<State>(() => raw) }
}

describe('persist: only the most recent hydration takes effect', () => {
  it('a slow initial hydration does not overwrite a newer rehydrate()', async () => {
    const { reads, storage } = controlledStorage()
    const store = createStore<State>()(
      persist(() => ({ ...initial }), { name: 'user-1', storage }),
    )
    const finished = vi.fn()
    store.persist.onFinishHydration(finished)
    expect(reads).toHaveLength(1)

    store.persist.setOptions({ name: 'user-2' })
    const latest = store.persist.rehydrate()
    expect(reads.map((r) => r.name)).toEqual(['user-1', 'user-2'])

    reads[1]!.result.resolve(stored({ user: 'bob', count: 2 }))
    await latest
    expect(store.getState()).toEqual({ user: 'bob', count: 2 })
    expect(store.persist.hasHydrated()).toBe(true)
    expect(finished).toHaveBeenCalledTimes(1)

    reads[0]!.result.resolve(stored({ user: 'alice', count: 1 }))
    await flush()
    expect(store.getState()).toEqual({ user: 'bob', count: 2 })
    expect(store.persist.hasHydrated()).toBe(true)
    expect(finished).toHaveBeenCalledTimes(1)
  })

  it('a superseded hydration that finishes first does not complete hydration', async () => {
    const { reads, storage } = controlledStorage()
    const store = createStore<State>()(
      persist(() => ({ ...initial }), {
        name: 'app',
        storage,
        skipHydration: true,
      }),
    )
    const finished = vi.fn()
    store.persist.onFinishHydration(finished)

    const first = store.persist.rehydrate()
    const second = store.persist.rehydrate()
    expect(reads).toHaveLength(2)

    reads[0]!.result.resolve(stored({ user: 'alice', count: 1 }))
    await flush()
    expect(store.getState()).toEqual(initial)
    expect(store.persist.hasHydrated()).toBe(false)
    expect(finished).not.toHaveBeenCalled()

    reads[1]!.result.resolve(stored({ user: 'bob', count: 2 }))
    await second
    expect(store.getState()).toEqual({ user: 'bob', count: 2 })
    expect(store.persist.hasHydrated()).toBe(true)
    expect(finished).toHaveBeenCalledTimes(1)
    expect(finished).toHaveBeenCalledWith({ user: 'bob', count: 2 })

    await first
    expect(store.getState()).toEqual({ user: 'bob', count: 2 })
    expect(finished).toHaveBeenCalledTimes(1)
  })

  it('a hydration superseded while its async migrate is pending is dropped', async () => {
    const { reads, setItem, storage } = controlledStorage()
    const migration = deferred<State>()
    const migrate = vi.fn(() => migration.promise)
    const store = createStore<State>()(
      persist(() => ({ ...initial }), {
        name: 'app',
        storage,
        version: 1,
        migrate,
        skipHydration: true,
      }),
    )
    const finished = vi.fn()
    store.persist.onFinishHydration(finished)

    const first = store.persist.rehydrate()
    reads[0]!.result.resolve(stored({ user: 'alice-v0', count: 1 }, 0))
    await flush()
    expect(migrate).toHaveBeenCalledTimes(1)

    const second = store.persist.rehydrate()
    reads[1]!.result.resolve(stored({ user: 'bob', count: 2 }, 1))
    await second
    expect(store.getState()).toEqual({ user: 'bob', count: 2 })

    migration.resolve({ user: 'alice-migrated', count: 1 })
    await first
    await flush()
    expect(store.getState()).toEqual({ user: 'bob', count: 2 })
    expect(setItem).not.toHaveBeenCalled()
    expect(store.persist.hasHydrated()).toBe(true)
    expect(finished).toHaveBeenCalledTimes(1)
  })

  it('keeps one-at-a-time hydrations working, including migration write-back', async () => {
    const { reads, setItem, storage } = controlledStorage()
    const store = createStore<State>()(
      persist(() => ({ ...initial }), {
        name: 'app',
        storage,
        version: 1,
        migrate: (persisted) => ({ ...(persisted as State), user: 'migrated' }),
      }),
    )
    const finished = vi.fn()
    store.persist.onFinishHydration(finished)

    reads[0]!.result.resolve(stored({ user: 'alice', count: 1 }, 0))
    await flush()
    expect(store.getState()).toEqual({ user: 'migrated', count: 1 })
    expect(store.persist.hasHydrated()).toBe(true)
    expect(finished).toHaveBeenCalledTimes(1)
    expect(setItem).toHaveBeenCalledTimes(1)
    expect(JSON.parse(setItem.mock.calls[0]![1])).toEqual({
      state: { user: 'migrated', count: 1 },
      version: 1,
    })

    const again = store.persist.rehydrate()
    reads[1]!.result.resolve(stored({ user: 'carol', count: 3 }, 1))
    await again
    expect(store.getState()).toEqual({ user: 'carol', count: 3 })
    expect(store.persist.hasHydrated()).toBe(true)
    expect(finished).toHaveBeenCalledTimes(2)
    expect(finished).toHaveBeenLastCalledWith({ user: 'carol', count: 3 })
  })
})

