import { afterEach, beforeEach, expect, it, vi } from 'vitest'
import { devtools } from 'zustand/middleware'
import { createStore } from 'zustand/vanilla'

type CounterState = { count: number; inc: () => void }

function makeExtension() {
  const connection = {
    init: vi.fn(),
    send: vi.fn(),
    error: vi.fn(),
    subscribe: vi.fn(() => () => {}),
    unsubscribe: vi.fn(),
  }
  const extension = { connect: vi.fn(() => connection) }
  return { extension, connection }
}

function counter(options: Parameters<typeof devtools>[1]) {
  return createStore<CounterState>()(
    devtools(
      (set) => ({
        count: 0,
        inc: () => set((s) => ({ count: s.count + 1 }), false, 'inc'),
      }),
      options,
    ),
  )
}

let savedExtension: unknown
beforeEach(() => {
  savedExtension = (window as any).__REDUX_DEVTOOLS_EXTENSION__
})
afterEach(() => {
  ;(window as any).__REDUX_DEVTOOLS_EXTENSION__ = savedExtension
})

it('exposes a no-op devtools.cleanup when enabled is false', () => {
  const { extension, connection } = makeExtension()
  ;(window as any).__REDUX_DEVTOOLS_EXTENSION__ = extension
  const store = counter({ name: 'zd11-disabled', enabled: false })

  expect(extension.connect).not.toHaveBeenCalled()
  expect((store as any).devtools).toBeDefined()
  expect(typeof (store as any).devtools?.cleanup).toBe('function')
  expect(() => store.devtools.cleanup()).not.toThrow()
  expect(() => store.devtools.cleanup()).not.toThrow()
  expect(connection.unsubscribe).not.toHaveBeenCalled()
})

it('exposes a no-op devtools.cleanup when the extension is not installed', () => {
  ;(window as any).__REDUX_DEVTOOLS_EXTENSION__ = undefined
  const store = counter({ name: 'zd11-missing', enabled: true })

  expect((store as any).devtools).toBeDefined()
  expect(typeof (store as any).devtools?.cleanup).toBe('function')
  expect(() => store.devtools.cleanup()).not.toThrow()
})

it('keeps the store working when devtools is inactive', () => {
  ;(window as any).__REDUX_DEVTOOLS_EXTENSION__ = undefined
  const store = counter({ name: 'zd11-state', store: 'counter' })
  const listener = vi.fn()
  store.subscribe(listener)

  store.getState().inc()
  store.setState({ count: 10 }, false, 'setTen')
  expect(store.getState().count).toBe(10)
  expect(listener).toHaveBeenCalledTimes(2)

  store.devtools.cleanup()
  store.getState().inc()
  expect(store.getState().count).toBe(11)
})

it('still connects, sends and unsubscribes when enabled', () => {
  const { extension, connection } = makeExtension()
  ;(window as any).__REDUX_DEVTOOLS_EXTENSION__ = extension
  const store = counter({ name: 'zd11-enabled', enabled: true })

  expect(extension.connect).toHaveBeenCalledTimes(1)
  store.getState().inc()
  expect(connection.send).toHaveBeenLastCalledWith(
    { type: 'inc' },
    expect.objectContaining({ count: 1 }),
  )
  store.devtools.cleanup()
  expect(connection.unsubscribe).toHaveBeenCalledTimes(1)
})

