import { afterEach, beforeEach, expect, it, vi } from 'vitest'
import { devtools } from 'zustand/middleware'
import { createStore } from 'zustand/vanilla'

type Listener = (message: unknown) => void

// Mimics the Redux DevTools connection API: subscribe() returns a function
// that removes that one listener, unsubscribe() drops every listener.
function makeExtension() {
  const connections: Array<{
    options: any
    listeners: Set<Listener>
    init: ReturnType<typeof vi.fn>
    send: ReturnType<typeof vi.fn>
    error: ReturnType<typeof vi.fn>
    subscribe: ReturnType<typeof vi.fn>
    unsubscribe: ReturnType<typeof vi.fn>
    emit: (message: unknown) => void
  }> = []
  const extension = {
    connect: vi.fn((options: any) => {
      const listeners = new Set<Listener>()
      const connection = {
        options,
        listeners,
        init: vi.fn(),
        send: vi.fn(),
        error: vi.fn(),
        subscribe: vi.fn((listener: Listener) => {
          listeners.add(listener)
          return () => {
            listeners.delete(listener)
          }
        }),
        unsubscribe: vi.fn(() => {
          listeners.clear()
        }),
        emit: (message: unknown) => {
          ;[...listeners].forEach((listener) => listener(message))
        },
      }
      connections.push(connection)
      return connection
    }),
  }
  return { extension, connections }
}

const counter = (name: string, store?: string) =>
  createStore(
    devtools(() => ({ count: 0 }), {
      name,
      enabled: true,
      ...(store === undefined ? {} : { store }),
    }),
  )

const jumpTo = (state: unknown) => ({
  type: 'DISPATCH',
  payload: { type: 'JUMP_TO_STATE' },
  state: JSON.stringify(state),
})

let savedExtension: unknown
let ext: ReturnType<typeof makeExtension>
beforeEach(() => {
  savedExtension = (window as any).__REDUX_DEVTOOLS_EXTENSION__
  ext = makeExtension()
  ;(window as any).__REDUX_DEVTOOLS_EXTENSION__ = ext.extension
})
afterEach(() => {
  ;(window as any).__REDUX_DEVTOOLS_EXTENSION__ = savedExtension
})

it('cleaning up one store keeps the shared connection alive for the others', () => {
  const a = counter('zd12-shared-1', 'a')
  const b = counter('zd12-shared-1', 'b')
  expect(ext.extension.connect).toHaveBeenCalledTimes(1)
  const [conn] = ext.connections

  a.devtools.cleanup()
  expect(conn!.unsubscribe).not.toHaveBeenCalled()

  conn!.emit(jumpTo({ a: { count: 5 }, b: { count: 7 } }))
  expect(b.getState()).toEqual({ count: 7 })

  b.setState({ count: 8 }, false, 'setEight')
  expect(conn!.send).toHaveBeenLastCalledWith(
    { type: 'b/setEight' },
    expect.objectContaining({ b: { count: 8 } }),
  )
})

it('a cleaned-up store no longer reacts to devtools messages', () => {
  const a = counter('zd12-shared-2', 'a')
  const b = counter('zd12-shared-2', 'b')
  const c = counter('zd12-shared-2', 'c')
  const [conn] = ext.connections

  b.devtools.cleanup()
  conn!.emit(jumpTo({ a: { count: 1 }, b: { count: 2 }, c: { count: 3 } }))
  expect(a.getState()).toEqual({ count: 1 })
  expect(b.getState()).toEqual({ count: 0 })
  expect(c.getState()).toEqual({ count: 3 })

  conn!.emit({
    type: 'ACTION',
    payload: JSON.stringify({ type: '__setState', state: { b: { count: 9 } } }),
  })
  conn!.emit({
    type: 'ACTION',
    payload: JSON.stringify({ type: '__setState', state: { c: { count: 4 } } }),
  })
  expect(b.getState()).toEqual({ count: 0 })
  expect(c.getState()).toEqual({ count: 4 })
})

it('unsubscribes the shared connection only when its last store is cleaned up', () => {
  const a = counter('zd12-shared-3', 'a')
  const b = counter('zd12-shared-3', 'b')
  const [conn] = ext.connections

  b.devtools.cleanup()
  expect(conn!.unsubscribe).not.toHaveBeenCalled()
  a.devtools.cleanup()
  expect(conn!.unsubscribe).toHaveBeenCalledTimes(1)

  // a new store under the same name starts a fresh connection
  const c = counter('zd12-shared-3', 'c')
  expect(ext.extension.connect).toHaveBeenCalledTimes(2)
  const fresh = ext.connections[1]!
  c.setState({ count: 2 }, false, 'two')
  expect(fresh.send).toHaveBeenLastCalledWith(
    { type: 'c/two' },
    { c: { count: 2 } },
  )
})

it('stores without the `store` option still unsubscribe on cleanup', () => {
  const solo = counter('zd12-solo')
  const [conn] = ext.connections
  solo.devtools.cleanup()
  expect(conn!.unsubscribe).toHaveBeenCalledTimes(1)
})

