let unsubscribeListener: (() => void) | undefined
;(api as StoreApi<S> & StoreDevtools<S>).devtools = {
  cleanup: () => {
    if (connectionInformation.type === 'tracked') {
      unsubscribeListener?.()
      unsubscribeListener = undefined
      removeStoreFromTrackedConnections(options.name, store)
      if (Object.keys(connectionInformation.stores).length > 0) return
    }
    if (
      connection &&
      typeof (connection as any).unsubscribe === 'function'
    ) {
      ;(connection as any).unsubscribe()
    }
  },
}
